  // ---- ./src/find-panel.js
  const findPanel = (() => {
    // The find panel that lives in the RIGHT sidebar, as a tab of its own: the right
    // column is where the reader's auxiliary panels already are, and it opens beside
    // the conversation instead of replacing it.
    //
    // The tab system wants three registrations sharing one id (the shape the shipped
    // context/schedule panels use): the tab type, the panel body, and the title chip.
    //
    // The search engine is the DOM-layer controller's `search`/`revealAt`: folded
    // content is always in the DOM, so a hit inside a folded message or step block
    // is found and then revealed by unfolding exactly what hides it.

    function createFindPanel(React, api) {
      const h = React.createElement

      /** The tab's chip text. */
      function Title() {
        return h('span', { 'data-lf-find-chip': '1' }, '查找')
      }

      function Panel() {
        const [query, setQuery] = React.useState('')
        const [hits, setHits] = React.useState([])
        const [active, setActive] = React.useState(0)
        const inputRef = React.useRef?.(null)
        const jumpRef = React.useRef?.(() => {})

        const run = (next) => {
          setQuery(next)
          const found = api.search(next)
          setHits(found)
          setActive(found.length > 0 ? 0 : -1)
        }
        const jump = (index) => {
          const hit = hits[index]
          if (!hit) return
          setActive(index)
          api.revealAt(hit.element)
        }
        jumpRef.current = jump

        // Focus the input whenever the panel opens (keyboard route included).
        React.useEffect(() => {
          api.onFindPanelMounted?.(() => {
            const input = inputRef.current
            if (input && typeof input.focus === 'function') input.focus()
          })
        }, [])

        return h('div', { 'data-lf-find': '1' },
          h('div', { 'data-lf-find-head': '1' },
            h('input', {
              ref: inputRef,
              type: 'text',
              placeholder: '搜索本会话（含折叠内容）',
              value: query,
              onChange: (event) => run(event.target.value),
              onKeyDown: (event) => {
                if (event.key === 'Enter') {
                  if (event.shiftKey) jump(Math.max(0, active - 1))
                  else jump(Math.min(hits.length - 1, active + 1))
                } else if (event.key === 'Escape') {
                  run('')
                }
              }
            }),
            h('span', { 'data-lf-find-count': '1' }, query ? `${active + 1} / ${hits.length}` : '')),
          h('div', { 'data-lf-find-list': '1' },
            hits.length === 0 && query !== ''
              ? h('div', { 'data-lf-find-empty': '1' }, '没有匹配。折叠起来的内容也会被搜索。')
              : hits.map((hit, index) => h('button', {
                key: `${hit.kind}:${index}`,
                type: 'button',
                'data-lf-find-row': '1',
                'data-lf-find-active': index === active ? '1' : '0',
                title: hit.kind === 'message' ? '跳到这条消息' : '跳到这一步',
                onClick: () => jump(index)
              }, h('span', { 'data-lf-find-kind': '1' }, hit.kind === 'message' ? '消息' : '步骤'),
              h('span', { 'data-lf-find-snippet': '1' }, hit.snippet)))))
      }

      return { Panel, Title }
    }

    return { createFindPanel }
  })()

  // ---- ./src/turn-timer.js
  const turnTimer = (() => {
    // Per-turn duration chips — pure logic plus a tiny plain store.
    //
    // Data source (read-only, display-only like the rest of this plugin): the chat
    // snapshot's settled nodes, each carrying `turn` and `timing`
    // { stepStartTime, firstTokenTime, completedTime }. A Turn's duration is the
    // span from its FIRST step's start to its LAST step's completion — i.e. from
    // the host beginning to process the command to the final output landing.
    // (Verified pattern against gbeta/dsh-token-speed lib/client.js, MIT.)
    //
    // No DOM access here, so everything is unit-testable in plain Node.

    /**
     * Human label for a duration: seconds below a minute ("3.2秒" / "42秒"),
     * minutes above ("1分12秒"). Invalid input yields ''.
     */
    function formatDuration(ms) {
      const value = Number(ms)
      if (!Number.isFinite(value) || value < 0) return ''
      const seconds = value / 1000
      if (seconds < 60) return `${seconds < 10 ? seconds.toFixed(1) : Math.round(seconds)}秒`
      const minutes = Math.floor(seconds / 60)
      const rest = Math.round(seconds % 60)
      return `${minutes}分${rest}秒`
    }

    /**
     * Fold settled assistant nodes into { turn: milliseconds }.
     * A step without usable timing is skipped; a Turn with no timed step has no
     * entry, which is exactly what the DOM layer needs to leave it chip-less.
     */
    function turnDurations(nodes) {
      const spans = {}
      if (!Array.isArray(nodes)) return {}
      for (const node of nodes) {
        if (!node || node.kind !== 'assistant') continue
        const timing = node.timing
        if (!timing) continue
        const start = timing.stepStartTime
        const end = timing.completedTime
        if (typeof start !== 'number' || typeof end !== 'number') continue
        if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) continue
        const key = Number(node.turn)
        if (!Number.isFinite(key)) continue
        const span = spans[key] ?? (spans[key] = { start, end })
        if (start < span.start) span.start = start
        if (end > span.end) span.end = end
      }
      const durations = {}
      for (const key of Object.keys(spans)) durations[key] = spans[key].end - spans[key].start
      return durations
    }

    /** Plain observable store bridging the snapshot probe and the DOM pass. */
    function createTurnTimerStore() {
      let durations = {}
      const listeners = new Set()
      return {
        get: () => durations,
        set(next) {
          durations = next && typeof next === 'object' ? next : {}
          for (const listener of [...listeners]) {
            try { listener(durations) } catch { /* one bad listener must not break the rest */ }
          }
        },
        subscribe(fn) {
          if (typeof fn !== 'function') return () => {}
          listeners.add(fn)
          return () => listeners.delete(fn)
        },
        clear() {
          durations = {}
          for (const listener of [...listeners]) {
            try { listener(durations) } catch { /* ignore */ }
          }
        }
      }
    }

    return { formatDuration, turnDurations, createTurnTimerStore }
  })()

  MODULES['./src/fold.js'] = fold
  MODULES['./src/browser.js'] = browser
  MODULES['./src/settings-panel.js'] = settingsPanel
  MODULES['./src/find-panel.js'] = findPanel

  // Convenience handle for verifying or driving the plugin from the console:
  //   __DSH_BUBBLE_FOLD__.settings() / .update({...}) / .rescan()
  window.__DSH_BUBBLE_FOLD_MODULES__ = { ...(window.__DSH_BUBBLE_FOLD_MODULES__ ?? {}), ...MODULES }

